// plugins/godot-mcp-pro/server/build/tools/navigation-tools.js
function createNavigationTools() {
  return [
    defineGodotTool({
      id: "setup_navigation_region",
      description: "Add a NavigationRegion2D/3D child to a node with auto-created NavigationPolygon or NavigationMesh. Auto-detects 2D/3D from parent context.",
      inputSchema: {
        node_path: external_exports.string().describe("Path to the parent node to add the region to"),
        mode: external_exports.string().optional().describe("Force '2d' or '3d' mode, or 'auto' to detect from parent (default: auto)"),
        name: external_exports.string().optional().describe("Name for the NavigationRegion node"),
        navigation_layers: external_exports.number().optional().describe("Navigation layers bitmask"),
        agent_radius: external_exports.number().optional().describe("Agent radius for mesh generation (3D default: 0.5, 2D: from NavigationPolygon)"),
        agent_height: external_exports.number().optional().describe("Agent height (3D only, default: 1.5)"),
        agent_max_climb: external_exports.number().optional().describe("Max climb height (3D only, default: 0.25)"),
        agent_max_slope: external_exports.number().optional().describe("Max slope angle in degrees (3D only, default: 45.0)"),
        cell_size: external_exports.number().optional().describe("Cell size for navigation mesh (default: 0.25 for 3D)"),
        cell_height: external_exports.number().optional().describe("Cell height (3D only, default: 0.25)"),
        source_geometry_mode: external_exports.string().optional().describe("2D only: root_node, groups_with_children, or groups_explicit")
      },
      category: "navigation",
      permission: {
        key: "godot_setup_navigation_region",
        operation: "mutate",
        resourcePatterns: ["godot://project/navigation"]
      }
    }),
    defineGodotTool({
      id: "bake_navigation_mesh",
      description: "Bake navigation mesh for a NavigationRegion3D, or set outline vertices and generate polygons for a NavigationRegion2D.",
      inputSchema: {
        node_path: external_exports.string().describe("Path to the NavigationRegion2D or NavigationRegion3D node"),
        outline: external_exports.array(external_exports.union([
          external_exports.array(external_exports.number()).describe("[x, y] coordinate pair"),
          external_exports.object({ x: external_exports.number(), y: external_exports.number() })
        ])).optional().describe("2D only: Array of outline vertices as [x,y] pairs or {x,y} objects. At least 3 vertices required.")
      },
      category: "navigation",
      permission: {
        key: "godot_bake_navigation_mesh",
        operation: "mutate",
        resourcePatterns: ["godot://project/navigation"]
      }
    }),
    defineGodotTool({
      id: "setup_navigation_agent",
      description: "Add a NavigationAgent2D/3D child to a node and configure pathfinding and avoidance properties. Auto-detects 2D/3D from parent context.",
      inputSchema: {
        node_path: external_exports.string().describe("Path to the parent node to add the agent to"),
        mode: external_exports.string().optional().describe("Force '2d' or '3d' mode, or 'auto' to detect from parent (default: auto)"),
        name: external_exports.string().optional().describe("Name for the NavigationAgent node"),
        path_desired_distance: external_exports.number().optional().describe("Distance threshold to advance to next path point"),
        target_desired_distance: external_exports.number().optional().describe("Distance threshold to consider target reached"),
        radius: external_exports.number().optional().describe("Agent radius for avoidance"),
        neighbor_distance: external_exports.number().optional().describe("Max distance to consider other agents as neighbors"),
        max_neighbors: external_exports.number().optional().describe("Max number of neighbors for avoidance"),
        max_speed: external_exports.number().optional().describe("Maximum movement speed for avoidance"),
        avoidance_enabled: external_exports.boolean().optional().describe("Enable avoidance behavior"),
        navigation_layers: external_exports.number().optional().describe("Navigation layers bitmask for pathfinding queries")
      },
      category: "navigation",
      permission: {
        key: "godot_setup_navigation_agent",
        operation: "mutate",
        resourcePatterns: ["godot://project/navigation"]
      }
    }),
    defineGodotTool({
      id: "set_navigation_layers",
      description: "Set navigation layers for a NavigationRegion or NavigationAgent. Supports bitmask value, layer bit numbers, or named layers from ProjectSettings.",
      inputSchema: {
        node_path: external_exports.string().describe("Path to a NavigationRegion2D/3D or NavigationAgent2D/3D node"),
        layers: external_exports.number().optional().describe("Navigation layers as a bitmask value (e.g. 5 = layers 1 and 3)"),
        layer_bits: external_exports.array(external_exports.number()).optional().describe("Array of 1-based layer numbers to enable (e.g. [1, 3] = bitmask 5)"),
        layer_names: external_exports.array(external_exports.string()).optional().describe("Array of named layer names from ProjectSettings (layer_names/2d_navigation/layer_N or 3d)")
      },
      category: "navigation",
      permission: {
        key: "godot_set_navigation_layers",
        operation: "mutate",
        resourcePatterns: ["godot://project/navigation"]
      }
    }),
    defineGodotTool({
      id: "get_navigation_info",
      description: "Get navigation setup info for a node and its subtree: all NavigationRegions, NavigationAgents, their layers, and mesh/polygon data.",
      inputSchema: {
        node_path: external_exports.string().describe("Path to the root node to inspect")
      },
      category: "navigation",
      permission: {
        key: "godot_get_navigation_info",
        operation: "read",
        resourcePatterns: ["godot://project/navigation"]
      }
    })
  ];
}

