// plugins/godot-mcp-pro/server/build/tools/test-tools.js
function createTestTools() {
  return [
    defineGodotTool({
      id: "run_test_scenario",
      description: "Execute a test scenario in the running game. Optionally plays a scene, then runs a sequence of steps (input simulation, waits, assertions, screenshots). Returns pass/fail summary. Note: keep scenarios short (under 20 seconds total) to avoid timeout.",
      inputSchema: {
        scene_path: external_exports.string().optional().describe("Scene to play before running steps. Use 'main' for main scene, 'current' for current scene, or a res:// path. If omitted, uses already-running scene."),
        steps: external_exports.array(external_exports.record(external_exports.string(), external_exports.unknown())).describe("Array of test steps. Each step has a 'type' field: 'input' (action/keycode simulation), 'wait' (seconds or node_path to wait for), 'assert' (node_path+property+expected+operator, or text for screen text), 'screenshot' (capture a frame). Examples: {type:'input', action:'ui_accept'}, {type:'wait', seconds:0.5}, {type:'wait', node_path:'/root/Main/Player'}, {type:'assert', node_path:'/root/Main/Player', property:'health', expected:100, operator:'eq'}, {type:'assert', text:'Game Over'}, {type:'screenshot'}")
      },
      category: "test",
      permission: {
        key: "godot_run_test_scenario",
        operation: "runtime",
        resourcePatterns: ["godot://runtime/tests"]
      }
    }),
    defineGodotTool({
      id: "assert_node_state",
      description: "Assert a node's property value in the running game. Compares the actual property value against an expected value using the specified operator. Returns pass/fail with actual value for debugging.",
      inputSchema: {
        node_path: external_exports.string().describe("Absolute node path in the running game (e.g. '/root/Main/Player')"),
        property: external_exports.string().describe("Property name to check (e.g. 'health', 'position:x', 'visible')"),
        expected: external_exports.union([external_exports.string(), external_exports.number(), external_exports.boolean()]).describe("Expected value to compare against"),
        operator: external_exports.enum(["eq", "neq", "gt", "lt", "gte", "lte", "contains", "type_is"]).optional().describe("Comparison operator (default: 'eq'). eq/neq: equality, gt/lt/gte/lte: numeric comparison, contains: string/array contains, type_is: check Godot type name")
      },
      category: "test",
      permission: {
        key: "godot_assert_node_state",
        operation: "runtime",
        resourcePatterns: ["godot://runtime/tests"]
      }
    }),
    defineGodotTool({
      id: "assert_screen_text",
      description: "Assert that specific text is visible on screen in the running game. Searches all visible UI elements (Button, Label, LineEdit, etc.) for matching text. Useful for verifying UI state, dialog content, or game messages.",
      inputSchema: {
        text: external_exports.string().describe("Text to search for on screen (e.g. 'Game Over', 'Score:', 'New Game')"),
        partial: external_exports.boolean().optional().describe("Allow partial text matching (default: true). If false, requires exact match."),
        case_sensitive: external_exports.boolean().optional().describe("Case-sensitive comparison (default: true)")
      },
      category: "test",
      permission: {
        key: "godot_assert_screen_text",
        operation: "runtime",
        resourcePatterns: ["godot://runtime/tests"]
      }
    }),
    defineGodotTool({
      id: "run_stress_test",
      description: "Run rapid random input events for a specified duration and check if the game crashes. Sends random UI actions (up/down/left/right/accept/cancel) plus any custom actions. Returns whether the game survived, event count, and new errors.",
      inputSchema: {
        duration: external_exports.number().optional().describe("Duration in seconds to run the stress test (1-60, default: 5)"),
        actions: external_exports.array(external_exports.string()).optional().describe("Additional input action names to include in random input pool (e.g. ['jump', 'attack', 'dash'])")
      },
      category: "test",
      permission: {
        key: "godot_run_stress_test",
        operation: "runtime",
        resourcePatterns: ["godot://runtime/tests"]
      }
    }),
    defineGodotTool({
      id: "get_test_report",
      description: "Collect and format results from all assertions run so far (via assert_node_state, assert_screen_text, and run_test_scenario) into a summary test report. Shows pass/fail counts, pass rate, and detailed results.",
      inputSchema: {
        clear: external_exports.boolean().optional().describe("Clear accumulated results after generating report (default: true)")
      },
      category: "test",
      permission: {
        key: "godot_get_test_report",
        operation: "runtime",
        resourcePatterns: ["godot://runtime/tests"]
      }
    })
  ];
}

